#   generic : loose topical mention                      (WEAK)
#   exclude : lexical false friends, masked out before matching
#   spec_direct  : regex over normalised specialties enum (lowercase, letters only) -> service-specific enum
#   spec_related : parent specialty enum (necessary-ish, far from sufficient)
#   coreq   : co-requirement name -> regex searched over ALL text of the facility
